package main

const refillPage = `<!doctype html>
<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Linode 补号与账户池</title><style>
:root{color-scheme:dark;--bg:#0b1120;--card:#132039;--line:#2b3e5e;--muted:#9aafcb;--blue:#6eabff;--text:#e7eef9}*{box-sizing:border-box}body{margin:0;background:radial-gradient(at top left,#193351,transparent 55%),var(--bg);font:14px/1.65 system-ui,sans-serif;color:var(--text)}header{border-bottom:1px solid var(--line);padding:18px 24px;display:flex;justify-content:space-between;gap:16px;background:#0c1728}a{color:var(--blue);text-decoration:none}main{max-width:1180px;margin:auto;padding:28px 22px}h1{font-size:28px;margin:0}h2{font-size:18px;margin:0 0 14px}p{color:var(--muted)}.eyebrow{color:var(--blue);font-size:11px;letter-spacing:2px}.hero{display:flex;justify-content:space-between;align-items:center;gap:16px;margin-bottom:24px}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:22px 0}.card,section{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px}.card span{display:block;color:var(--muted);font-size:12px}.card strong{display:block;font-size:20px;overflow-wrap:anywhere;margin-top:7px}section{margin-bottom:18px}.grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}.three{grid-template-columns:repeat(3,1fr)}label{display:flex;flex-direction:column;gap:7px;color:var(--muted)}input,select,textarea,button{font:inherit;border-radius:9px;border:1px solid #385174;background:#0b172a;color:var(--text);padding:10px;min-height:43px}input,select,textarea{width:100%;min-width:0}textarea{font-family:ui-monospace,monospace;resize:vertical}button{cursor:pointer;padding:9px 15px;background:#213857}button:hover{border-color:var(--blue)}button:disabled{opacity:.45;cursor:wait}.primary{background:#347fe7;border-color:#347fe7}.danger{color:#ffb3b9}.check{display:flex;flex-direction:row;align-items:center;gap:9px}.check input{width:18px;min-height:18px;height:18px}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:14px 0}.hint{font-size:12px;margin:10px 0;color:var(--muted)}.notice{padding:12px 16px;border:1px solid #5b5260;border-radius:12px;background:#2b2837;color:#e1c8af}.tablewrap{overflow:auto}table{width:100%;border-collapse:collapse;min-width:700px}th,td{text-align:left;border-bottom:1px solid var(--line);padding:12px 8px;vertical-align:top}th{color:var(--muted);font-weight:500}td button{font-size:12px;padding:6px 9px;min-height:32px;margin:2px}td small{display:block;color:var(--muted)}.queueitem{display:flex;gap:10px;align-items:center;background:#0d192d;padding:10px 12px;border-radius:10px;margin:7px 0}.queueitem span{flex:1;overflow-wrap:anywhere}.queueitem button{min-height:30px;padding:3px 10px}.message{white-space:pre-wrap;overflow-wrap:anywhere;color:#b7d6ff}.error{color:#ffabb7}pre{white-space:pre-wrap;overflow-wrap:anywhere;max-height:330px;overflow:auto;background:#0b1526;border-radius:10px;padding:15px;color:#b8cbe6;font:12px/1.8 ui-monospace,monospace}summary{cursor:pointer;color:var(--blue);padding:10px 0}button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,a:focus-visible{outline:2px solid var(--blue);outline-offset:3px}.spanall{grid-column:1/-1}[hidden]{display:none!important}@media(max-width:700px){.grid,.three{grid-template-columns:1fr}.cards{grid-template-columns:1fr 1fr}header{padding:14px}.hero{align-items:flex-start}main{padding:20px 14px}.card,section{padding:16px}.card strong{font-size:16px}.hero h1{font-size:24px}}
</style></head><body><header><strong>LINODE / 自动运维</strong><a href="/">返回节点管理 →</a></header><main>
<div class="hero"><div><span class="eyebrow">ACCOUNT POOL &amp; SERVICE HANDOFF</span><h1>补号与账户池</h1><p>Token / API 异常时自动检测候选账号，验证通过后建机、检查 IP 并执行脚本。</p></div><button onclick="refreshAll()">刷新数据</button></div>
<div class="notice">切号条件：Linode 确认 Token / 权限异常，或 API 连续三轮连接失败。候选账号先测试 API，再建机；限流和临时服务错误先等待。额度只提醒，流量与旧机 TCP 不参与切号。</div>
<div class="cards"><div class="card"><span>自动补号</span><strong id="runstate">载入中</strong></div><div class="card"><span>当前账号 / 实例</span><strong id="current">—</strong></div><div class="card"><span>当前 IP</span><strong id="currentip">—</strong></div><div class="card"><span>剩余估算额度</span><strong id="credit">尚未检查</strong><small id="cursor"></small></div></div>
<p id="message" class="message" role="status" aria-live="polite"></p><p id="apifailures" class="hint"></p>
<section><h2>01 / 账户池与出口记录</h2><label class="check"><input id="strict" type="checkbox" onchange="saveStrict()">所有 Linode 请求强制使用账号绑定代理，并在请求前验证、记录出口 IP</label><p class="hint">补号任务始终强制代理隔离。代理故障、出口检测失败或出口曾被其他账号使用时阻止请求，不回退直连。检测服务不接收 Linode Token；出口检测不能保证平台无法关联账号。</p>
<div class="tablewrap"><table><thead><tr><th>账号</th><th>绑定代理</th><th>最近检测出口 IP</th><th>API 检查</th><th>操作</th></tr></thead><tbody id="accountrows"></tbody></table></div>
<details><summary>添加账号 / 配置代理池</summary><div class="grid three"><label>账号名称<input id="accountname" maxlength="80"></label><label>API Token<input id="accounttoken" type="password" autocomplete="new-password"></label><label>独占代理<select id="accountproxy"></select></label></div><div class="toolbar"><button onclick="addAccount()">添加账号</button><a href="/#overview">在原面板管理账号和代理绑定 →</a></div><label>导入代理（每行：名称|完整代理 URL）<textarea id="proxybatch" rows="3" placeholder="出口A|socks5://用户:密码@主机:端口"></textarea></label><button onclick="importProxies()">保存代理</button><p class="hint">代理凭据加密保存，不在列表回显。禁止共用同一代理端点；不同代理端点仍会检查是否共用出口 IP。</p></details>
<details><summary>出口 IP 使用历史</summary><div class="tablewrap"><table><thead><tr><th>账号</th><th>IP / 代理端点</th><th>首次 / 最近检测</th><th>检测次数</th></tr></thead><tbody id="egressrows"></tbody></table></div><p class="hint">这是代理检测服务观察到的出口历史，不是 Linode 平台登录记录。账号移除后仍保留历史，避免重新分配已使用出口。</p></details></section>
<section><h2>02 / 使用顺序</h2><div class="toolbar"><select id="queueadd" aria-label="添加到队列的账号"></select><button onclick="addQueue()">加入队列</button></div><div id="queue"></div><p class="hint">按顺序使用，不循环复用耗尽账号；队列耗尽时暂停并提醒。修改顺序后需要保存配置。</p></section>
<section><h2>03 / 建机与接替策略</h2><div class="grid three"><label>地区<select id="region"></select></label><label>套餐<select id="type"></select></label><label>镜像<select id="image"></select></label><label>实例名前缀<input id="label" maxlength="36"></label><label>剩余额度提醒阈值 / USD（不触发切号）<input id="credit_floor" type="number" min="0" step="0.1"></label><label>每隔多少分钟检查<input id="interval_minutes" type="number" min="1" max="60"></label><label>开机检测端口<input id="check_port" type="number" min="1" max="65535"></label><label>部署完成后业务检查端口<input id="health_port" type="number" min="1" max="65535"></label><label>接替域名（可留空）<input id="domain" placeholder="node.example.com"></label><label>旧机策略<select id="old_policy"><option value="keep">保留，人工处理</option><option value="shutdown">新机接替后请求关机（仍计费）</option></select></label><div><button onclick="loadCatalogs()">加载地区 / 套餐 / 镜像</button><p class="hint">使用队列首个账号查询。</p></div></div>
<div class="toolbar"><label class="check"><input id="boot_check" type="checkbox">开机时从阿里云国内机检查 IP</label><label class="check"><input id="auto_ip" type="checkbox">国内不通时持续换 IP，直到通过（无次数上限）</label></div>
<label>开机脚本（IP 检查通过后执行）<textarea id="script" rows="7" placeholder="#!/bin/bash&#10;# 安装应用、写入配置、配置 systemd 开机自启"></textarea></label><p class="hint">新建接替实例及从本页开机时，在 IP 检查通过后通过 SSH 执行。可用环境变量：LNM_ACCOUNT_ID、LNM_INSTANCE_ID、LNM_IPV4。脚本失败不会自动重试；人工恢复可能再次执行，脚本应保持幂等。业务数据迁移需要写入脚本。脚本输出不写入面板任务日志。</p>
<details><summary>绑定已有实例（可选）</summary><div class="grid"><label>当前账号<select id="current_account"></select></label><label>实例 ID<input id="current_instance" type="number" min="0" placeholder="0 表示从队列首个账号新建"></label></div><p class="hint">绑定仅核实实例，不安装或修改现有业务。留 0 才会在首次执行时创建实例。</p></details>
<div class="toolbar"><label class="check"><input id="enabled" type="checkbox">保存后启用后台自动检查及付费建机 / 换 IP</label><button class="primary" onclick="saveConfig()">保存配置</button><button onclick="runAction('pause')">暂停 / 安全停止</button></div><p class="hint">当前任务运行时不能修改配置；未开启自动补号也可手动执行。额度按赠金适用服务、有效期和月度上限计算，并保守预留未结算账单；API 数据存在延迟，无法保证零超额费用。余额达到提醒阈值只通知。当前账号 API 认证或权限明确失败时直接进入候选检测；连接失败须累计三轮，每轮至少间隔一分钟，中途恢复清零。候选只做只读 API 检查，不创建测试机器；通过后仍可能因写权限、配额或地区容量而建机失败。</p></section>
<section><h2>04 / 阿里云国内探测机</h2><div class="grid"><label>国内服务器 IPv4<input id="probehost" autocomplete="off"></label><label>SSH 端口<input id="probeport" type="number" value="22"></label><label>SSH 用户名<input id="probeuser" value="root" autocomplete="off"></label><label>SSH 密码（留空保留）<input id="probepassword" type="password" autocomplete="new-password"></label></div><div class="toolbar"><button onclick="saveProbe()">验证连接并加密保存</button><span id="probestatus" class="hint"></span></div><p class="hint">新机先等检测端口从管理机连通，再从国内机检查。国内探测机失联不判为 IP 被墙。此处与原面板共享国内探测机配置。</p></section>
<section><h2>05 / 任务与流量</h2><div class="toolbar"><button class="primary" data-task onclick="runAction('run')">立即检查 / 执行接替</button><button data-task onclick="runAction('probe')">国内 IP 检查</button><button data-task onclick="runAction('boot')">开机并检查</button><button data-task onclick="runAction('change-ip')">原机换 IP</button><button data-task onclick="runAction('resume')">核对并恢复未完成建机</button><button onclick="loadTransfer()">查询当前流量</button></div><p class="hint">换 IP 保留磁盘，国内检查不通过时串行持续重试，每轮留有间隔，可安全停止；申请额外 IPv4 可能需要配额并产生费用，会短暂停机。创建结果不明时保留意图，恢复只按标签寻找同一实例，不重复建机。入口 DNS 凭据在原面板的 DNS 设置中配置；留空域名时入口须由脚本处理。</p><pre id="transfer">尚未查询流量</pre><pre id="pending" hidden></pre><pre id="history"></pre></section>
</main><script>
const $=id=>document.getElementById(id);let accounts=[],proxies=[],queue=[],state=null,taskBusy=false,mutating=false;
async function api(path,options={}){const response=await fetch('/api'+path,{...options,headers:{'Content-Type':'application/json'},credentials:'same-origin'});if(response.status===401&&response.headers.get('X-LNM-Auth-Required')==='true'){location.assign('/login');throw Error('登录已过期')}const data=await response.json();if(!response.ok)throw Error(data.error||'请求失败');return data}
function message(text,error=false){$('message').textContent=text;$('message').className=error?'message error':'message'}
async function mutate(fn){if(mutating)return;mutating=true;try{await fn()}catch(e){message(e.message,true)}finally{mutating=false}}
function option(select,value,text){const o=document.createElement('option');o.value=value;o.textContent=text;select.appendChild(o);return o}
function name(id){return accounts.find(a=>a.id===id)?.name||id}
function renderQueue(){const root=$('queue');root.replaceChildren();queue.forEach((id,index)=>{const row=document.createElement('div');row.className='queueitem';const title=document.createElement('span');title.textContent=(index+1)+'. '+name(id);row.appendChild(title);for(const [text,offset]of [['↑',-1],['↓',1],['移除',0]]){const b=document.createElement('button');b.textContent=text;b.disabled=offset<0&&index===0||offset>0&&index===queue.length-1;b.onclick=()=>{if(offset===0)queue.splice(index,1);else{const other=index+offset;[queue[index],queue[other]]=[queue[other],queue[index]]}renderQueue()};row.appendChild(b)}root.appendChild(row)})}
function addQueue(){const id=$('queueadd').value;if(id&&!queue.includes(id)){queue.push(id);renderQueue()}}
function cell(row,text){const td=document.createElement('td');td.textContent=text;row.appendChild(td);return td}
async function loadAccounts(){const [a,p,h]=await Promise.all([api('/accounts'),api('/proxy-pool'),api('/account-pool')]);accounts=a.accounts;proxies=p.proxies;$('strict').checked=h.strict;for(const id of ['queueadd','current_account']){const sel=$(id),old=sel.value;sel.replaceChildren();option(sel,'','请选择账号');accounts.forEach(a=>option(sel,a.id,a.name));sel.value=old}const select=$('accountproxy');select.replaceChildren();option(select,'','请选择未占用代理');for(const p of proxies){const o=option(select,p.id,p.name+' · '+p.address);o.disabled=Boolean(p.bound_accounts?.length)}$('accountrows').replaceChildren();for(const a of accounts){const row=document.createElement('tr'),proxy=proxies.find(p=>p.bound_accounts?.includes(a.id)),hist=h.history.find(x=>x.account_id===a.id),last=hist?.records?.slice().sort((a,b)=>b.last_seen.localeCompare(a.last_seen))[0];cell(row,a.name);cell(row,proxy?proxy.name+' · '+proxy.address:'未绑定池内代理');cell(row,last?last.ip+' · '+last.last_seen:'尚未检测');const apiCell=cell(row,apiCheckText(state?.api_checks?.[a.id]));apiCell.id='api-status-'+a.id;const actions=cell(row,'');const apiTest=document.createElement('button');apiTest.textContent='测试 API';apiTest.onclick=()=>testAccountAPI(a.id);actions.appendChild(apiTest);const check=document.createElement('button');check.textContent='检测并记录出口';check.onclick=()=>mutate(async()=>{const result=await api('/accounts/'+encodeURIComponent(a.id)+'/egress',{method:'POST',body:'{}'});message(a.name+' 出口 IP：'+result.ip);await loadAccounts()});actions.appendChild(check);const add=document.createElement('button');add.textContent='加入队列';add.onclick=()=>{if(!queue.includes(a.id)){queue.push(a.id);renderQueue()}};actions.appendChild(add);const binding=document.createElement('select');option(binding,'','解除绑定');for(const entry of proxies){const o=option(binding,entry.id,entry.name);o.disabled=Boolean(entry.bound_accounts?.some(id=>id!==a.id))}binding.value=proxy?.id||'';const bind=document.createElement('button');bind.textContent='保存代理绑定';bind.onclick=()=>mutate(async()=>{await api('/proxy-pool?account_id='+encodeURIComponent(a.id),{method:'PUT',body:JSON.stringify({id:binding.value})});await loadAccounts();message('账号代理绑定已保存')});actions.appendChild(binding);actions.appendChild(bind);$('accountrows').appendChild(row)}$('egressrows').replaceChildren();for(const item of h.history)for(const record of item.records||[]){const row=document.createElement('tr');cell(row,name(item.account_id));cell(row,record.ip+' / '+record.proxy);cell(row,record.first_seen+' / '+record.last_seen);cell(row,String(record.uses));$('egressrows').appendChild(row)}renderQueue()}
const textFields=['region','type','image','label','domain','script','old_policy'];const numberFields=['credit_floor','interval_minutes','check_port','health_port'];const boolFields=['boot_check','auto_ip','enabled'];
async function loadState(fill=false){const result=await api('/refill');state=result.state;taskBusy=result.busy;$('runstate').textContent=(state.config.enabled?'自动检查已启用 · ':'已暂停 · ')+state.stage;$('current').textContent=state.current_instance?name(state.current_account)+' / #'+state.current_instance:'未绑定实例';$('currentip').textContent=state.current_ip||'—';$('cursor').textContent=(state.cursor>=state.config.accounts.length?'无后续账号':(state.cursor+1)+' / '+state.config.accounts.length);$('credit').textContent=state.current_credit==null?'尚未检查':'$'+Number(state.current_credit).toFixed(2);for(const a of accounts){const target=$('api-status-'+a.id);if(target)target.textContent=apiCheckText(state.api_checks?.[a.id])}document.getElementById('apifailures').textContent='当前 API 连续连接失败：'+(state.api_failures||0)+'/3';$('history').textContent=((state.history||[]).map(x=>x.at+' '+x.message).join('\n')||'暂无任务记录')+'\n\n历史实例：\n'+(state.retired||[]).map(x=>name(x.account_id)+' / #'+x.instance_id+' / '+x.ip+' / '+(x.shutdown_requested?'已请求关机':'保留')).join('\n');$('pending').hidden=!state.pending;$('pending').textContent=state.pending?'未完成实例：'+state.pending.account_id+' / '+state.pending.label+' / #'+state.pending.instance_id:'';for(const b of document.querySelectorAll('[data-task]'))b.disabled=taskBusy;if(fill){queue=[...(state.config.accounts||[])];for(const key of textFields){if(['region','type','image'].includes(key)&&state.config[key])option($(key),state.config[key],state.config[key]);$(key).value=state.config[key]||''}for(const key of numberFields)$(key).value=state.config[key];for(const key of boolFields)$(key).checked=state.config[key];$('current_account').value=state.current_account||'';$('current_instance').value=state.current_instance||0;renderQueue()}}
async function refreshAll(){try{await loadAccounts();await loadState(!state);const probe=await api('/domestic-probe/settings');$('probehost').value=probe.host||'';$('probeport').value=probe.port||22;$('probeuser').value=probe.user||'root';$('probestatus').textContent=probe.configured?'已配置并验证':'尚未配置'}catch(e){message(e.message,true)}}
async function loadCatalogs(){try{const account=queue[0]||$('queueadd').value;if(!account)throw Error('请先选择队列账号');for(const kind of ['regions','types','images']){const result=await api('/catalog/'+kind+'?account_id='+encodeURIComponent(account)+'&use_proxy=true');const id={regions:'region',types:'type',images:'image'}[kind],sel=$(id),old=sel.value;sel.replaceChildren();for(const item of result.data)option(sel,item.id,(item.label||item.id)+(kind==='types'&&item.price?' · $'+item.price.monthly+'/月':''));if(old)sel.value=old}message('地区、套餐和镜像已更新')}catch(e){message(e.message,true)}}
async function saveConfig(){await mutate(async()=>{const config={trigger:'api',accounts:queue};for(const k of textFields)config[k]=$(k).value.trim();config.script=$('script').value;for(const k of numberFields)config[k]=Number($(k).value);for(const k of boolFields)config[k]=$(k).checked;if(config.enabled&&!confirm('启用后将按队列自动创建付费实例、执行脚本，并可能付费换 IP。确认启用？'))return;await api('/refill',{method:'PUT',body:JSON.stringify({config,current_account:$('current_account').value,current_instance:Number($('current_instance').value||0)})});message('配置已加密保存');await loadState(true)})}
async function runAction(action){await mutate(async()=>{if(taskBusy&&action!=='pause')throw Error('任务正在运行，请等待');if(action==='resume'&&!confirm('请先在 Linode 核对记录中的实例。恢复只使用同一实例，可能再次执行初始化脚本；脚本必须支持重复执行。确认恢复？'))return;if(['run','boot','change-ip'].includes(action)&&!confirm('此操作可能创建付费实例、启动实例或更换付费 IPv4；换 IP 会短暂停机。确认执行？'))return;await api('/refill/'+action,{method:'POST',body:JSON.stringify({confirm_billing:action!=='probe'})});message(action==='pause'?'正在暂停后续检查 / 安全停止当前任务':'任务已提交，日志会自动更新');await loadState()})}
async function saveStrict(){await mutate(async()=>{const enabled=$('strict').checked;if(enabled&&!confirm('开启后，所有账号的 Linode 请求都必须使用独占代理。未绑定代理或出口检测失败将被阻止。继续？')){$('strict').checked=false;return}await api('/account-pool',{method:'PUT',body:JSON.stringify({strict:enabled})});message('全局代理隔离设置已保存')})}
function apiCheckText(check){return check?(check.message+' · '+check.checked_at):'尚未测试'}
async function testAccountAPI(id){await mutate(async()=>{const result=await api('/accounts/'+encodeURIComponent(id)+'/api-check',{method:'POST',body:'{}'});message(name(id)+'：'+result.message,result.kind!=='ok');await loadState()})}
async function addAccount(){await mutate(async()=>{if(!$('accountproxy').value)throw Error('请选择独占代理');await api('/accounts',{method:'POST',body:JSON.stringify({name:$('accountname').value,token:$('accounttoken').value,proxy_id:$('accountproxy').value})});$('accounttoken').value='';$('accountname').value='';await loadAccounts();message('账号已添加并绑定独占代理')})}
async function importProxies(){await mutate(async()=>{const proxies=$('proxybatch').value.split('\n').map(x=>x.trim()).filter(Boolean).map(line=>{const p=line.indexOf('|');if(p<1)throw Error('每行格式：名称|代理URL');return{name:line.slice(0,p),url:line.slice(p+1)}});await api('/proxy-pool',{method:'POST',body:JSON.stringify({lines:proxies.map(p=>p.name+'|'+p.url).join('\n')})});$('proxybatch').value='';await loadAccounts();message('代理已保存')})}
async function saveProbe(){await mutate(async()=>{await api('/domestic-probe/settings',{method:'POST',body:JSON.stringify({host:$('probehost').value,port:Number($('probeport').value),user:$('probeuser').value,password:$('probepassword').value})});$('probepassword').value='';$('probestatus').textContent='连接验证通过，已加密保存';message('阿里云国内探测机已就绪')})}
async function loadTransfer(){try{if(!state?.current_instance)throw Error('请先保存当前实例');const account=encodeURIComponent(state.current_account);const [pool,instance]=await Promise.all([api('/accounts/'+account+'/transfer'),api('/instances/'+state.current_instance+'/transfer?account_id='+account)]);$('transfer').textContent='账号流量池（GB；仅查看，不触发切换）\n'+JSON.stringify(pool,null,2)+'\n实例流量（used / bytes_* 为字节，quota 为 GB）\n'+JSON.stringify(instance,null,2)}catch(e){message(e.message,true)}}
refreshAll();setInterval(()=>loadState().catch(e=>message(e.message,true)),5000);
</script></body></html>`
